/**
 * three.js renderer for the resource pipeline.
 *
 * The scene consumes *our own* formats: the terrain is built from the same ATT/MAP/OBJ structures the
 * server and the tests use, and the character mesh comes from a BMD model through
 * `parseBmd → extractMeshGeometry`. In this environment the data is generated by
 * `packages/mu-formats/src/testing/fixtures.ts` (no proprietary assets); when real files are available
 * the loader swaps the fixture builders for file reads without touching the renderer.
 */

import * as THREE from 'three';

import {
  buildAttFixture,
  buildBmdFixture,
  buildMapFixture,
  buildObjFixture,
  extractMeshGeometry,
  parseAtt,
  parseBmd,
  parseMap,
  parseObj,
  TwFlags,
  type BmdModel,
  type MeshGeometry,
} from '@mu-reengineer/formats';

export interface RendererOptions {
  canvas: HTMLCanvasElement;
  /** Tile count rendered around the player (keeps the demo light); the maps have 256x256 tiles. */
  tileSpan: number;
}

export interface CharacterView {
  id: number;
  mesh: THREE.Object3D;
  x: number;
  y: number;
  targetX: number;
  targetY: number;
}

export interface TerrainStats {
  width: number;
  height: number;
  waterTiles: number;
  safeTiles: number;
  objects: number;
  meshVertices: number;
  meshTriangles: number;
}

const TILE_COLOR: Record<string, number> = {
  ground: 0x4a5d3a,
  water: 0x2b5d8a,
  noGround: 0x2f2f2f,
  safe: 0x6b7f4a,
};

export class MuRenderer {
  readonly scene = new THREE.Scene();
  readonly camera: THREE.PerspectiveCamera;
  private readonly renderer: THREE.WebGLRenderer;
  private readonly characterRoot = new THREE.Group();
  private readonly characters = new Map<number, CharacterView>();
  private readonly clock = new THREE.Clock();
  private readonly tileSpan: number;
  private model?: BmdModel;
  private frames = 0;
  private lastFpsUpdate = 0;
  private fps = 0;
  readonly stats: TerrainStats = {
    width: 0,
    height: 0,
    waterTiles: 0,
    safeTiles: 0,
    objects: 0,
    meshVertices: 0,
    meshTriangles: 0,
  };

  constructor(options: RendererOptions) {
    this.tileSpan = options.tileSpan;
    this.renderer = new THREE.WebGLRenderer({ canvas: options.canvas, antialias: true });
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    this.camera = new THREE.PerspectiveCamera(55, 1, 0.1, 2000);

    this.scene.background = new THREE.Color(0x0d1117);
    this.scene.fog = new THREE.Fog(0x0d1117, 60, 180);
    this.scene.add(new THREE.HemisphereLight(0xf0f6ff, 0x2a2c1f, 1.1));
    const sun = new THREE.DirectionalLight(0xffffff, 1.4);
    sun.position.set(60, 120, 40);
    this.scene.add(sun);
    this.scene.add(this.characterRoot);

    this.buildTerrain();
    this.model = parseBmd(buildBmdFixture({ version: 15, name: 'synthetic-hero' }).bytes);
  }

  /** Builds terrain + object meshes from the ATT/MAP/OBJ fixtures and fills {@link stats}. */
  private buildTerrain(): void {
    const att = parseAtt(buildAttFixture({ extended: true }).bytes);
    const map = parseMap(buildMapFixture().bytes);
    const obj = parseObj(buildObjFixture().bytes);

    this.stats.width = att.width + 1;
    this.stats.height = att.height + 1;
    this.stats.objects = obj.objects.length;

    const span = Math.min(this.tileSpan, this.stats.width);
    const offset = Math.floor((this.stats.width - span) / 2);
    // A grid with one segment per tile gives (span+1)^2 vertices; rotateX(-PI/2) puts the plane on
    // the XZ ground with the front face up, so a vertex (ix, iy) lands exactly on tile
    // (offset+ix, offset+iy) once the mesh is centred below.
    const geometry = new THREE.PlaneGeometry(span, span, span, span);
    geometry.rotateX(-Math.PI / 2);

    const colors = new Float32Array(geometry.attributes.position!.count * 3);
    const color = new THREE.Color();
    for (let i = 0; i < geometry.attributes.position!.count; i++) {
      // PlaneGeometry vertices run row-major over the span; sample the corresponding tile
      const gx = i % (span + 1);
      const gy = Math.floor(i / (span + 1));
      const tileIndex = (offset + Math.min(gy, this.stats.height - 1)) * this.stats.width + (offset + Math.min(gx, this.stats.width - 1));
      const flags = att.attributes[tileIndex] ?? 0;
      if (flags & TwFlags.Water) {
        this.stats.waterTiles += 1;
        color.setHex(TILE_COLOR.water!);
      } else if (flags & TwFlags.NoGround) {
        color.setHex(TILE_COLOR.noGround!);
      } else if (flags & TwFlags.SafeZone) {
        this.stats.safeTiles += 1;
        color.setHex(TILE_COLOR.safe!);
      } else {
        color.setHex(TILE_COLOR.ground!);
      }
      // a light per-tile variation driven by the texture-index layers, so the pattern is visible
      const textureIndex = (map.layer1[tileIndex] ?? 0) + (map.layer2[tileIndex] ?? 0);
      const shade = 0.75 + ((textureIndex % 8) / 8) * 0.5;
      color.multiplyScalar(shade);
      colors[i * 3] = color.r;
      colors[i * 3 + 1] = color.g;
      colors[i * 3 + 2] = color.b;
    }
    geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));

    const terrain = new THREE.Mesh(
      geometry,
      new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.95, metalness: 0.05 }),
    );
    terrain.name = 'terrain';
    terrain.position.set(offset + span / 2, 0, offset + span / 2);
    this.scene.add(terrain);

    // objects from the OBJ record list (positions are tile coordinates)
    const objectMaterial = new THREE.MeshStandardMaterial({ color: 0x8a6f4e, roughness: 0.8 });
    for (const record of obj.objects) {
      const box = new THREE.Mesh(new THREE.BoxGeometry(record.scale, record.scale * 2, record.scale), objectMaterial);
      box.position.set(record.position.x, record.scale, record.position.y);
      box.rotation.y = record.angle.z;
      this.scene.add(box);
    }
  }

  /** Creates (or updates) the visual representation of a character. */
  addCharacter(id: number, name: string, x: number, y: number): CharacterView {
    const existing = this.characters.get(id);
    if (existing) {
      existing.targetX = x;
      existing.targetY = y;
      return existing;
    }

    const group = new THREE.Group();
    group.name = `character-${name}`;
    if (this.model) {
      const mesh = buildMeshFromModel(this.model);
      this.stats.meshVertices = mesh.userData.vertexCount as number;
      this.stats.meshTriangles = mesh.userData.triangleCount as number;
      group.add(mesh);
    } else {
      group.add(new THREE.Mesh(new THREE.CapsuleGeometry(0.4, 1.2), new THREE.MeshStandardMaterial({ color: 0xd0a070 })));
    }
    const marker = new THREE.Mesh(new THREE.SphereGeometry(0.18), new THREE.MeshStandardMaterial({ color: 0x66ccff }));
    marker.position.set(0, 2.1, 0);
    group.add(marker);

    const view: CharacterView = { id, mesh: group, x, y, targetX: x, targetY: y };
    group.position.set(x, 0, y);
    this.characterRoot.add(group);
    this.characters.set(id, view);
    return view;
  }

  removeCharacter(id: number): void {
    const view = this.characters.get(id);
    if (!view) return;
    this.characterRoot.remove(view.mesh);
    this.characters.delete(id);
  }

  setTarget(id: number, x: number, y: number): void {
    const view = this.characters.get(id);
    if (!view) return;
    view.targetX = x;
    view.targetY = y;
  }

  getCharacter(id: number): CharacterView | undefined {
    return this.characters.get(id);
  }

  resize(width: number, height: number): void {
    this.renderer.setSize(width, height, false);
    this.camera.aspect = width / height;
    this.camera.updateProjectionMatrix();
  }

  get currentFps(): number {
    return this.fps;
  }

  /** Renders one frame: camera follow, smoothing and the FPS meter. */
  render(focus: { x: number; y: number }): void {
    const delta = this.clock.getDelta();
    for (const view of this.characters.values()) {
      const step = Math.min(1, delta * 12);
      view.x += (view.targetX - view.x) * step;
      view.y += (view.targetY - view.y) * step;
      view.mesh.position.set(view.x, 0, view.y);
    }

    this.camera.position.set(focus.x - 18, 26, focus.y + 24);
    this.camera.lookAt(focus.x, 0, focus.y);
    this.renderer.render(this.scene, this.camera);

    this.frames += 1;
    const now = performance.now();
    if (now - this.lastFpsUpdate >= 500) {
      this.fps = Math.round((this.frames * 1000) / (now - this.lastFpsUpdate));
      this.frames = 0;
      this.lastFpsUpdate = now;
    }
  }
}

/** Converts an extracted BMD geometry into a three.js mesh (non-indexed, one bone weight). */
function buildMeshFromModel(model: BmdModel): THREE.Mesh {
  const geometry: MeshGeometry = extractMeshGeometry(model.meshes[0]!);
  const buffer = new THREE.BufferGeometry();
  buffer.setAttribute('position', new THREE.BufferAttribute(geometry.positions, 3));
  buffer.setAttribute('normal', new THREE.BufferAttribute(geometry.normals, 3));
  buffer.setAttribute('uv', new THREE.BufferAttribute(geometry.uvs, 2));
  // Skeletal animation is not wired yet, so the bone indices are read but not used by the shader; the
  // mesh is drawn in bind pose (the animation clips from the BMD actions are the next step).
  buffer.computeVertexNormals();

  const mesh = new THREE.Mesh(
    buffer,
    new THREE.MeshStandardMaterial({ color: 0xcfcfd8, roughness: 0.6, metalness: 0.15, flatShading: true }),
  );
  mesh.userData.vertexCount = geometry.vertexCount;
  mesh.userData.triangleCount = geometry.triangleCount;
  return mesh;
}
